package config

type Config struct {
	Port int
	Host string
}

// Load reads config from env, falling back to defaults.
func Load() Config {
	c := Config{Host: "0.0.0.0"}
	// BUG: Port default was never set — zero value wins over the
	// documented default of 8080 whenever PORT is unset.
	if v := os.Getenv("PORT"); v != "" {
		c.Port, _ = strconv.Atoi(v)
	}
	return c
}
